window.__finlexDocLoaded(10180,{"id":10180,"articles":[{"id":1000751,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Governs goodwill impairment testing at the Reporting Unit level (single-step FV < carrying amount), indefinite/finite-lived intangibles, internal-use software (ASC 350-40), and fair value accounting for crypto assets (ASC 350-60, ASU 2023-08).","seq":0},{"id":1000752,"no":"ASC 350-20 / 350-40 / 350-60","heading":"Goodwill Reporting Units, Cloud Computing & Crypto Assets","text":"• Goodwill Impairment (ASC 350-20-35): Tested annually (or upon triggering event) at the Reporting Unit level (operating segment or one level below). Optional qualitative 'Step 0' screen; quantitative test compares Reporting Unit fair value to carrying amount (no reversal allowed).\n• Internal-Use Software & Cloud Computing (ASC 350-40): Capitalize application-development-stage costs and qualifying cloud implementation costs; expense preliminary and post-implementation costs.\n• Crypto Assets (ASC 350-60, ASU 2023-08, effective FY2025+): In-scope fungible crypto assets (e.g., Bitcoin, Ether) MUST be measured at fair value each period with changes in NET INCOME, presented separately on the balance sheet and income statement.","seq":1},{"id":1000753,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Goodwill Testing Level & Model: US GAAP tests at the Reporting Unit level using Fair Value only; IAS 36 tests at the CGU level using Recoverable Amount (higher of FVLCD and VIU).\n• Crypto Assets: ASC 350-60 mandates FVTPL for qualifying crypto assets; under IFRS (IFRIC Agenda Decision 2019), crypto is typically an indefinite-lived intangible under IAS 38 (cost model or revaluation through OCI).","seq":2},{"id":1000754,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
